def comps(coords, conn=8):
 coords=set(coords); out=[]
 while coords:
  seed=coords.pop(); comp={seed}; stack=[seed]
  while stack:
   r,c=stack.pop()
   for dr in [-1,0,1]:
    for dc in [-1,0,1]:
     if dr==dc==0: continue
     if conn==4 and abs(dr)+abs(dc)!=1: continue
     q=(r+dr,c+dc)
     if q in coords: coords.remove(q); comp.add(q); stack.append(q)
  out.append(comp)
 return sorted(out,key=len,reverse=True)
